export function radial(x=0,y=0,dead=.16){x=Number.isFinite(x)?x:0;y=Number.isFinite(y)?y:0;const m=Math.hypot(x,y);if(m<=dead)return [0,0];const p=Math.min(1,(m-dead)/(1-dead));return [x/m*p,y/m*p]}
export function layout(w,h,dpr=1,retro=true,mobile=false){w=Math.max(1,w);h=Math.max(1,h);const aspect=w/h,scale=Math.min(retro?1:Math.min(2,Math.max(1,dpr)),(retro?480:1080)/h,(retro?1280:mobile?1600:1920)/w,Math.sqrt((retro?614400:mobile?1400000:2073600)/(w*h)));return {width:Math.max(1,Math.round(w*scale)),height:Math.max(1,Math.round(h*scale)),aspect,fov:Math.min(104,Math.max(68,2*Math.atan(Math.tan(24*Math.PI/180)/aspect)*180/Math.PI))}}
export function padState(g,alternate=false){const a=g?.axes||[],b=g?.buttons||[],p=i=>!!(b[i]?.pressed||b[i]?.value>.55),v=i=>Number.isFinite(a[i])?a[i]:0;const [x,y]=radial(v(0),v(1)),start=g?.mapping==='standard'||!alternate?2:3,[rx,ry]=radial(v(start),v(start+1),.18),[mx,my]=radial(x+Number(p(15))-Number(p(14)),y+Number(p(13))-Number(p(12)),0);return {mx,my,rx,ry,up:p(5),down:p(4),buttons:Array.from({length:17},(_,i)=>p(i))}}
export function edge(now,old,i){return !!now[i]&&!old[i]}